package com.s23010526.hiddensrilanka;

import android.os.Bundle;
import android.text.TextUtils;
import android.util.Log;
import android.view.View;
import android.widget.ArrayAdapter;
import android.widget.AutoCompleteTextView;
import android.widget.EditText;
import android.widget.ImageView;
import android.widget.LinearLayout;
import android.widget.Toast;
import android.widget.ProgressBar;

import androidx.recyclerview.widget.LinearLayoutManager;
import androidx.recyclerview.widget.RecyclerView;

import com.bumptech.glide.Glide;
import com.google.android.material.button.MaterialButton;
import com.google.android.material.textfield.TextInputLayout;
import com.google.firebase.firestore.FirebaseFirestore;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

public class AddLocationActivity extends BaseActivity implements ImageGalleryAdapter.OnImageClickListener {

    private static final String TAG = "AddLocationActivity";

    // UI Components
    private EditText etLocationName, etDescription, etYoutubeUrl, etContributorName, etImageUrl;
    private AutoCompleteTextView etCategory, etCity, etProvince;
    private LinearLayout layoutGalleryPlaceholder;
    private MaterialButton btnSubmitLocation, btnLoadUrl, btnGooglePhotos, btnClearImages;
    private ProgressBar progressBar;
    private RecyclerView rvImageGallery;

    // Firebase
    private FirebaseFirestore firestore;

    // Image gallery data
    private ArrayList<String> imageUrls;
    private ImageGalleryAdapter imageGalleryAdapter;

    // Data structures for province-city mapping
    private Map<String, String[]> provinceCityMap;

    @Override
    protected int getLayoutResourceId() {
        return R.layout.activity_add_location;
    }

    @Override
    protected String getActivityTitle() {
        return "Add New Location";
    }

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);

        initializeViews();
        initializeFirebase();
        initializeProvinceCityMapping();
        setupDropdowns();
        setupImageGallery();
        setupClickListeners();
    }

    private void initializeViews() {
        etLocationName = findViewById(R.id.et_location_name);
        etDescription = findViewById(R.id.et_description);
        etYoutubeUrl = findViewById(R.id.et_youtube_url);
        etContributorName = findViewById(R.id.et_contributor_name);
        etImageUrl = findViewById(R.id.et_image_url);
        etCategory = findViewById(R.id.et_category);
        etCity = findViewById(R.id.et_city);
        etProvince = findViewById(R.id.et_province);
        layoutGalleryPlaceholder = findViewById(R.id.layout_gallery_placeholder);
        btnSubmitLocation = findViewById(R.id.btn_submit_location);
        btnLoadUrl = findViewById(R.id.btn_load_url);
        btnGooglePhotos = findViewById(R.id.btn_google_photos);
        btnClearImages = findViewById(R.id.btn_clear_images);
        progressBar = findViewById(R.id.progress_bar_submit);
        rvImageGallery = findViewById(R.id.rv_image_gallery);
    }

    private void initializeFirebase() {
        firestore = FirebaseFirestore.getInstance();
        Log.d(TAG, "Firestore initialized");
    }

    private void setupImageGallery() {
        // Initialize image gallery
        imageUrls = new ArrayList<>();
        imageGalleryAdapter = new ImageGalleryAdapter(this, imageUrls, true); // true = show remove buttons
        imageGalleryAdapter.setOnImageClickListener(this);

        rvImageGallery.setLayoutManager(new LinearLayoutManager(this, LinearLayoutManager.HORIZONTAL, false));
        rvImageGallery.setAdapter(imageGalleryAdapter);

        updateGalleryVisibility();
    }

    private void updateGalleryVisibility() {
        if (imageUrls.isEmpty()) {
            layoutGalleryPlaceholder.setVisibility(View.VISIBLE);
            btnClearImages.setVisibility(View.GONE);
        } else {
            layoutGalleryPlaceholder.setVisibility(View.GONE);
            btnClearImages.setVisibility(View.VISIBLE);
        }
    }

    private void setupClickListeners() {
        btnSubmitLocation.setOnClickListener(v -> validateAndSubmitLocation());
        btnLoadUrl.setOnClickListener(v -> loadImageFromUrl());
        btnGooglePhotos.setOnClickListener(v -> showGooglePhotosDialog());
        btnClearImages.setOnClickListener(v -> clearImageGallery());
    }

    private void loadImageFromUrl() {
        String url = etImageUrl.getText().toString().trim();

        if (TextUtils.isEmpty(url)) {
            etImageUrl.setError("Please enter an image URL");
            return;
        }

        if (!isValidUrl(url)) {
            etImageUrl.setError("Please enter a valid URL");
            return;
        }

        // Add image to gallery
        imageUrls.add(url);
        imageGalleryAdapter.notifyItemInserted(imageUrls.size() - 1);
        updateGalleryVisibility();

        // Clear the input field
        etImageUrl.setText("");

        Toast.makeText(this, "Image added to gallery!", Toast.LENGTH_SHORT).show();
    }

    private boolean isValidUrl(String url) {
        return url.startsWith("http://") || url.startsWith("https://");
    }

    private void showGooglePhotosDialog() {
        new androidx.appcompat.app.AlertDialog.Builder(this)
            .setTitle("Import from Google Photos")
            .setMessage("To add images from Google Photos:\n\n" +
                       "1. Open Google Photos app\n" +
                       "2. Select your photo\n" +
                       "3. Tap Share → Copy link\n" +
                       "4. Return here and paste the link\n" +
                       "5. Tap 'Add Image from URL'")
            .setPositiveButton("Got it!", null)
            .show();
    }

    private void clearImageGallery() {
        imageUrls.clear();
        imageGalleryAdapter.notifyDataSetChanged();
        updateGalleryVisibility();
        Toast.makeText(this, "Gallery cleared", Toast.LENGTH_SHORT).show();
    }

    // Implementation of ImageGalleryAdapter.OnImageClickListener
    @Override
    public void onImageClick(int position, String imageUrl) {
        // Show full screen image or preview
        showImagePreview(imageUrl);
    }

    @Override
    public void onImageRemove(int position) {
        imageUrls.remove(position);
        imageGalleryAdapter.notifyItemRemoved(position);
        imageGalleryAdapter.notifyItemRangeChanged(position, imageUrls.size());
        updateGalleryVisibility();
        Toast.makeText(this, "Image removed", Toast.LENGTH_SHORT).show();
    }

    private void showImagePreview(String imageUrl) {
        // Create a simple dialog to show full image
        View dialogView = getLayoutInflater().inflate(android.R.layout.select_dialog_item, null);
        ImageView imageView = new ImageView(this);
        imageView.setScaleType(ImageView.ScaleType.CENTER_INSIDE);
        imageView.setPadding(20, 20, 20, 20);

        Glide.with(this)
            .load(imageUrl)
            .into(imageView);

        new androidx.appcompat.app.AlertDialog.Builder(this)
            .setTitle("Image Preview")
            .setView(imageView)
            .setPositiveButton("Close", null)
            .show();
    }

    private void initializeProvinceCityMapping() {
        provinceCityMap = new HashMap<>();
        provinceCityMap.put("Western Province", new String[]{
            "Colombo", "Gampaha", "Kalutara", "Negombo", "Panadura", "Moratuwa"
        });
        provinceCityMap.put("Central Province", new String[]{
            "Kandy", "Matale", "Nuwara Eliya", "Gampola", "Nawalapitiya"
        });
        provinceCityMap.put("Southern Province", new String[]{
            "Galle", "Matara", "Hambantota", "Tangalle", "Mirissa"
        });
        // Add other provinces as needed
    }

    private void setupDropdowns() {
        // Categories dropdown
        String[] categories = {
            "Historical Site", "WaterFall", "Beach", "Mountain", "Temple",
            "National Park", "Cave", "Lake", "Village", "Cultural Site"
        };
        ArrayAdapter<String> categoryAdapter = new ArrayAdapter<>(this,
            android.R.layout.simple_dropdown_item_1line, categories);
        etCategory.setAdapter(categoryAdapter);

        // Provinces dropdown
        String[] provinces = provinceCityMap.keySet().toArray(new String[0]);
        ArrayAdapter<String> provinceAdapter = new ArrayAdapter<>(this,
            android.R.layout.simple_dropdown_item_1line, provinces);
        etProvince.setAdapter(provinceAdapter);

        // Setup province selection listener
        etProvince.setOnItemClickListener((parent, view, position, id) -> {
            String selectedProvince = parent.getItemAtPosition(position).toString();
            updateCityDropdown(selectedProvince);
        });
    }

    private void updateCityDropdown(String selectedProvince) {
        String[] cities = provinceCityMap.get(selectedProvince);
        if (cities != null) {
            ArrayAdapter<String> cityAdapter = new ArrayAdapter<>(this,
                android.R.layout.simple_dropdown_item_1line, cities);
            etCity.setAdapter(cityAdapter);
            etCity.setText("");
        }
    }

    private void validateAndSubmitLocation() {
        String locationName = etLocationName.getText().toString().trim();
        String description = etDescription.getText().toString().trim();
        String category = etCategory.getText().toString().trim();
        String city = etCity.getText().toString().trim();
        String contributorName = etContributorName.getText().toString().trim();
        String youtubeUrl = etYoutubeUrl.getText().toString().trim();
        String province = etProvince.getText().toString().trim();

        // Validation
        if (TextUtils.isEmpty(locationName)) {
            etLocationName.setError("Location name is required");
            etLocationName.requestFocus();
            return;
        }

        if (TextUtils.isEmpty(description)) {
            etDescription.setError("Description is required");
            etDescription.requestFocus();
            return;
        }

        if (TextUtils.isEmpty(category)) {
            etCategory.setError("Category is required");
            etCategory.requestFocus();
            return;
        }

        if (TextUtils.isEmpty(city)) {
            etCity.setError("City is required");
            etCity.requestFocus();
            return;
        }

        if (TextUtils.isEmpty(contributorName)) {
            etContributorName.setError("Your name is required");
            etContributorName.requestFocus();
            return;
        }

        if (TextUtils.isEmpty(province)) {
            etProvince.setError("Province is required");
            etProvince.requestFocus();
            return;
        }

        // Check if at least one image URL is provided
        if (imageUrls.isEmpty()) {
            Toast.makeText(this, "Please add at least one image", Toast.LENGTH_SHORT).show();
            return;
        }

        // Submit the location
        submitLocation(locationName, description, category, city, contributorName, youtubeUrl, province);
    }

    private void submitLocation(String locationName, String description, String category,
                              String city, String contributorName, String youtubeUrl, String province) {
        progressBar.setVisibility(View.VISIBLE);

        // Create location data map
        Map<String, Object> locationData = new HashMap<>();
        locationData.put("name", locationName);
        locationData.put("description", description);
        locationData.put("category", category);
        locationData.put("city", city);
        locationData.put("province", province);
        locationData.put("contributorName", contributorName);
        locationData.put("contributedAt", System.currentTimeMillis());
        locationData.put("youtubeUrl", youtubeUrl.isEmpty() ? "" : youtubeUrl);
        locationData.put("images", imageUrls); // Multiple images

        // Save to Firestore
        firestore.collection("cities")
                .document(city)
                .collection("attractions")
                .add(locationData)
                .addOnSuccessListener(documentReference -> {
                    progressBar.setVisibility(View.GONE);
                    Toast.makeText(this, "Location added successfully!", Toast.LENGTH_LONG).show();
                    clearForm();
                })
                .addOnFailureListener(e -> {
                    progressBar.setVisibility(View.GONE);
                    Toast.makeText(this, "Error: " + e.getMessage(), Toast.LENGTH_LONG).show();
                });
    }

    private void clearForm() {
        etLocationName.setText("");
        etDescription.setText("");
        etCategory.setText("");
        etCity.setText("");
        etProvince.setText("");
        etContributorName.setText("");
        etYoutubeUrl.setText("");
        etImageUrl.setText("");

        clearImageGallery();
    }
}

package com.s23010526.hiddensrilanka;

import android.app.Activity;
import android.content.Context;
import android.content.Intent;
import android.util.Log;

import androidx.annotation.NonNull;

import com.google.android.gms.auth.api.signin.GoogleSignIn;
import com.google.android.gms.auth.api.signin.GoogleSignInAccount;
import com.google.android.gms.auth.api.signin.GoogleSignInClient;
import com.google.android.gms.auth.api.signin.GoogleSignInOptions;
import com.google.android.gms.common.api.Scope;
import com.google.android.gms.tasks.Task;
import com.google.api.client.extensions.android.http.AndroidHttp;
import com.google.api.client.googleapis.extensions.android.gms.auth.GoogleAccountCredential;
import com.google.api.client.json.gson.GsonFactory;
import com.google.api.services.photoslibrary.v1.PhotosLibrary;
import com.google.api.services.photoslibrary.v1.PhotosLibraryScopes;
import com.google.api.services.photoslibrary.v1.model.ListSharedAlbumsResponse;
import com.google.api.services.photoslibrary.v1.model.SearchMediaItemsRequest;
import com.google.api.services.photoslibrary.v1.model.SearchMediaItemsResponse;
import com.google.api.services.photoslibrary.v1.model.SharedAlbum;
import com.google.api.services.photoslibrary.v1.model.MediaItem;

import java.io.IOException;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

/**
 * Helper class for Google Photos integration
 * Handles authentication and photo retrieval from shared albums
 */
public class GooglePhotosHelper {

    private static final String TAG = "GooglePhotosHelper";
    private static final int RC_GOOGLE_PHOTOS_SIGN_IN = 9001;

    private Context context;
    private GoogleSignInClient signInClient;
    private PhotosLibrary photosLibraryService;
    private ExecutorService executorService;

    // Interface for handling results
    public interface GooglePhotosCallback {
        void onAuthenticationSuccess();
        void onAuthenticationFailed(String error);
        void onPhotosLoaded(List<PhotoItem> photos);
        void onError(String error);
    }

    // Data class for photo items
    public static class PhotoItem {
        private String id;
        private String baseUrl;
        private String filename;
        private String description;
        private String mimeType;

        public PhotoItem(String id, String baseUrl, String filename, String description, String mimeType) {
            this.id = id;
            this.baseUrl = baseUrl;
            this.filename = filename;
            this.description = description;
            this.mimeType = mimeType;
        }

        // Getters
        public String getId() { return id; }
        public String getBaseUrl() { return baseUrl; }
        public String getFilename() { return filename; }
        public String getDescription() { return description; }
        public String getMimeType() { return mimeType; }

        // Get downloadable URL with specific dimensions
        public String getDownloadUrl(int width, int height) {
            return baseUrl + "=w" + width + "-h" + height;
        }

        // Get thumbnail URL
        public String getThumbnailUrl() {
            return baseUrl + "=w300-h300-c";
        }

        // Get full resolution URL
        public String getFullResolutionUrl() {
            return baseUrl + "=d";
        }
    }

    public GooglePhotosHelper(Context context) {
        this.context = context;
        this.executorService = Executors.newSingleThreadExecutor();
        initializeGoogleSignIn();
    }

    private void initializeGoogleSignIn() {
        GoogleSignInOptions gso = new GoogleSignInOptions.Builder(GoogleSignInOptions.DEFAULT_SIGN_IN)
                .requestEmail()
                .requestScopes(new Scope(PhotosLibraryScopes.PHOTOSLIBRARY_READONLY))
                .build();

        signInClient = GoogleSignIn.getClient(context, gso);
    }

    /**
     * Check if user is already signed in to Google Photos
     */
    public boolean isSignedIn() {
        GoogleSignInAccount account = GoogleSignIn.getLastSignedInAccount(context);
        return account != null && 
               GoogleSignIn.hasPermissions(account, new Scope(PhotosLibraryScopes.PHOTOSLIBRARY_READONLY));
    }

    /**
     * Sign in to Google Photos
     */
    public void signIn(Activity activity, GooglePhotosCallback callback) {
        if (isSignedIn()) {
            initializePhotosService();
            callback.onAuthenticationSuccess();
            return;
        }

        Intent signInIntent = signInClient.getSignInIntent();
        activity.startActivityForResult(signInIntent, RC_GOOGLE_PHOTOS_SIGN_IN);
    }

    /**
     * Handle sign-in result
     */
    public void handleSignInResult(Intent data, GooglePhotosCallback callback) {
        Task<GoogleSignInAccount> task = GoogleSignIn.getSignedInAccountFromIntent(data);

        try {
            GoogleSignInAccount account = task.getResult();
            if (account != null) {
                Log.d(TAG, "Google Photos sign-in successful");
                initializePhotosService();
                callback.onAuthenticationSuccess();
            } else {
                callback.onAuthenticationFailed("Failed to sign in to Google Photos");
            }
        } catch (Exception e) {
            Log.e(TAG, "Google Photos sign-in failed", e);
            callback.onAuthenticationFailed("Sign-in failed: " + e.getMessage());
        }
    }

    private void initializePhotosService() {
        GoogleSignInAccount account = GoogleSignIn.getLastSignedInAccount(context);
        if (account == null) {
            Log.e(TAG, "No signed-in account found");
            return;
        }

        GoogleAccountCredential credential = GoogleAccountCredential.usingOAuth2(
                context, Arrays.asList(PhotosLibraryScopes.PHOTOSLIBRARY_READONLY));
        credential.setSelectedAccount(account.getAccount());

        photosLibraryService = new PhotosLibrary.Builder(
                AndroidHttp.newCompatibleTransport(),
                GsonFactory.getDefaultInstance(),
                credential)
                .setApplicationName("Hidden Sri Lanka")
                .build();
    }

    /**
     * Load shared albums from Google Photos
     */
    public void loadSharedAlbums(GooglePhotosCallback callback) {
        if (photosLibraryService == null) {
            callback.onError("Google Photos service not initialized. Please sign in first.");
            return;
        }

        executorService.execute(() -> {
            try {
                ListSharedAlbumsResponse response = photosLibraryService.sharedAlbums().list().execute();
                List<SharedAlbum> albums = response.getSharedAlbums();

                if (albums != null && !albums.isEmpty()) {
                    // For demo, load photos from the first shared album
                    loadPhotosFromAlbum(albums.get(0).getId(), callback);
                } else {
                    ((Activity) context).runOnUiThread(() -> 
                        callback.onError("No shared albums found. Please make sure you have shared albums in Google Photos."));
                }

            } catch (IOException e) {
                Log.e(TAG, "Error loading shared albums", e);
                ((Activity) context).runOnUiThread(() -> 
                    callback.onError("Failed to load shared albums: " + e.getMessage()));
            }
        });
    }

    /**
     * Load all recent photos from Google Photos (not album-specific)
     */
    public void loadRecentPhotos(GooglePhotosCallback callback) {
        loadRecentPhotos(20, callback); // Load 20 recent photos
    }

    /**
     * Load recent photos with specified count
     */
    public void loadRecentPhotos(int pageSize, GooglePhotosCallback callback) {
        if (photosLibraryService == null) {
            callback.onError("Google Photos service not initialized. Please sign in first.");
            return;
        }

        executorService.execute(() -> {
            try {
                SearchMediaItemsRequest request = new SearchMediaItemsRequest()
                        .setPageSize(pageSize);

                SearchMediaItemsResponse response = photosLibraryService.mediaItems().search(request).execute();
                List<MediaItem> mediaItems = response.getMediaItems();

                List<PhotoItem> photoItems = new ArrayList<>();
                if (mediaItems != null) {
                    for (MediaItem item : mediaItems) {
                        // Only include images (not videos)
                        if (item.getMimeType() != null && item.getMimeType().startsWith("image/")) {
                            PhotoItem photoItem = new PhotoItem(
                                    item.getId(),
                                    item.getBaseUrl(),
                                    item.getFilename(),
                                    item.getDescription(),
                                    item.getMimeType()
                            );
                            photoItems.add(photoItem);
                        }
                    }
                }

                ((Activity) context).runOnUiThread(() -> callback.onPhotosLoaded(photoItems));

            } catch (IOException e) {
                Log.e(TAG, "Error loading recent photos", e);
                ((Activity) context).runOnUiThread(() -> 
                    callback.onError("Failed to load photos: " + e.getMessage()));
            }
        });
    }

    private void loadPhotosFromAlbum(String albumId, GooglePhotosCallback callback) {
        executorService.execute(() -> {
            try {
                SearchMediaItemsRequest request = new SearchMediaItemsRequest()
                        .setAlbumId(albumId)
                        .setPageSize(50);

                SearchMediaItemsResponse response = photosLibraryService.mediaItems().search(request).execute();
                List<MediaItem> mediaItems = response.getMediaItems();

                List<PhotoItem> photoItems = new ArrayList<>();
                if (mediaItems != null) {
                    for (MediaItem item : mediaItems) {
                        if (item.getMimeType() != null && item.getMimeType().startsWith("image/")) {
                            PhotoItem photoItem = new PhotoItem(
                                    item.getId(),
                                    item.getBaseUrl(),
                                    item.getFilename(),
                                    item.getDescription(),
                                    item.getMimeType()
                            );
                            photoItems.add(photoItem);
                        }
                    }
                }

                ((Activity) context).runOnUiThread(() -> callback.onPhotosLoaded(photoItems));

            } catch (IOException e) {
                Log.e(TAG, "Error loading photos from album", e);
                ((Activity) context).runOnUiThread(() -> 
                    callback.onError("Failed to load album photos: " + e.getMessage()));
            }
        });
    }

    /**
     * Sign out from Google Photos
     */
    public void signOut(GooglePhotosCallback callback) {
        signInClient.signOut().addOnCompleteListener(task -> {
            photosLibraryService = null;
            Log.d(TAG, "Signed out from Google Photos");
        });
    }

    /**
     * Clean up resources
     */
    public void cleanup() {
        if (executorService != null && !executorService.isShutdown()) {
            executorService.shutdown();
        }
    }

    public static int getSignInRequestCode() {
        return RC_GOOGLE_PHOTOS_SIGN_IN;
    }
}
